import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------- C++ header -------------------
cpp_source = """
#include <torch/extension.h>

torch::Tensor depthwise_conv2d_fp16(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding);
"""

# ------------------- CUDA implementation -------------------
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/ATen.h>

template <typename scalar_t>
__global__ void depthwise_conv2d_fp16_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int batch,
    int channels,
    int height,
    int width,
    int kernel,
    int stride,
    int padding,
    int height_out,
    int width_out)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * channels * height_out * width_out;
    if (idx >= total) return;

    int w_out = idx % width_out;
    int tmp   = idx / width_out;
    int h_out = tmp % height_out;
    tmp       = tmp / height_out;
    int c     = tmp % channels;
    int n     = tmp / channels;

    float sum = 0.0f;
    for (int kh = 0; kh < kernel; ++kh) {
        int h_in = h_out * stride - padding + kh;
        if (h_in < 0 || h_in >= height) continue;
        for (int kw = 0; kw < kernel; ++kw) {
            int w_in = w_out * stride - padding + kw;
            if (w_in < 0 || w_in >= width) continue;
            int input_idx  = ((n * channels + c) * height + h_in) * width + w_in;
            int weight_idx = (c * kernel + kh) * kernel + kw;
            sum += __half2float(input[input_idx]) *
                   __half2float(weight[weight_idx]);
        }
    }
    if (bias != nullptr) {
        sum += __half2float(bias[c]);
    }
    output[idx] = __float2half(sum);
}

torch::Tensor depthwise_conv2d_fp16(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf && weight.dtype() == torch::kHalf,
                "Only fp16 tensors are supported");
    const int batch    = input.size(0);
    const int channels = input.size(1);
    const int height   = input.size(2);
    const int width    = input.size(3);
    const int kernel   = weight.size(1); // weight shape (C, K, K)

    const int height_out = (height + 2 * padding - kernel) / stride + 1;
    const int width_out  = (width  + 2 * padding - kernel) / stride + 1;

    auto output = torch::empty({batch, channels, height_out, width_out},
                               input.options());

    const int threads = 256;
    const int total   = batch * channels * height_out * width_out;
    const int blocks  = (total + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "depthwise_conv2d_fp16_kernel", ([&] {
        depthwise_conv2d_fp16_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            weight.data_ptr<scalar_t>(),
            bias.defined() ? bias.data_ptr<scalar_t>() : nullptr,
            output.data_ptr<scalar_t>(),
            batch,
            channels,
            height,
            width,
            kernel,
            stride,
            padding,
            height_out,
            width_out);
    }));

    cudaDeviceSynchronize();
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("depthwise_conv2d_fp16", &depthwise_conv2d_fp16,
          "Depthwise Conv2d fp16 (CUDA)");
}
"""

# Compile the extension
depthwise_ext = load_inline(name="depthwise_ext",
                            cpp_sources=cpp_source,
                            cuda_sources=cuda_source,
                            functions=["depthwise_conv2d_fp16"],
                            verbose=False)

# ------------------- PyTorch model wrapper -------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference depthwise Conv2d.
    All tensors are fp16; accumulation is done in fp32 inside the kernel.
    """
    def __init__(self,
                 in_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.bias_flag = bias

        # weight shape: (C, K, K) – matches the kernel expectations
        self.weight = nn.Parameter(
            torch.empty(in_channels, kernel_size, kernel_size,
                        dtype=torch.float16, device='cuda')
        )
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)

        if bias:
            self.bias = nn.Parameter(
                torch.empty(in_channels, dtype=torch.float16, device='cuda')
            )
            nn.init.zeros_(self.bias)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.dtype != torch.float16:
            x = x.to(torch.float16)
        x = x.contiguous()
        w = self.weight.contiguous()
        b = self.bias.contiguous() if self.bias is not None else torch.tensor([], device='cuda')
        return depthwise_ext.depthwise_conv2d_fp16(
            x, w, b, self.stride, self.padding
        )
